"""Removing old snapshots."""
import os
import shutil


def list_snapshots(dest_root):
    """Return the snapshot folder names, oldest first by name."""
    return sorted(name for name in os.listdir(dest_root) if os.path.isdir(os.path.join(dest_root, name)))


def prune(dest_root, keep):
    """Delete all but the newest `keep` snapshots and return the removed names."""
    names = list_snapshots(dest_root)
    doomed = names[:-keep] if keep else names
    for name in doomed:
        shutil.rmtree(os.path.join(dest_root, name))
    return doomed

